    case VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_GEOMETRY_MOTION_TRIANGLES_DATA_NV:
        serialize_VkAccelerationStructureGeometryMotionTrianglesDataNV(buf, handles, *reinterpret_cast<const VkAccelerationStructureGeometryMotionTrianglesDataNV*>(p));
        break;
    case VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_GEOMETRY_SPHERES_DATA_NV:
        serialize_VkAccelerationStructureGeometrySpheresDataNV(buf, handles, *reinterpret_cast<const VkAccelerationStructureGeometrySpheresDataNV*>(p));
